import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 임직원 현황 메뉴의 이름 (menu.name)
const MENU_NAME = '임직원 현황';
// 가정: 열람 이력의 대상 정보 구분과 접근 유형
const TARGET_INFO_TYPE = '임직원 현황';
const ACCESS_TYPE = '조회';
// 가정: 휴직 현황은 발령 구분이 '휴직'인 발령 중 승인·마감 상태인 건이다
const LEAVE_TYPE = '휴직';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const STATUS_TYPES = ['입·퇴사', '휴직', '근속연수', '가족', '학력·경력'];
const SCOPE_RANK: Record<string, number> = { '전체': 0, '부서': 1, '개인': 2 };

function text(v: unknown): string | null {
  if (v === undefined || v === null) {
    return null;
  }
  const s = String(v).trim();
  return s === '' ? null : s;
}

function dateCond(expr: string): string {
  return '(CAST(:startDate AS date) IS NULL OR ' + expr + ' >= CAST(:startDate AS date))'
    + ' AND (CAST(:endDate AS date) IS NULL OR ' + expr + ' <= CAST(:endDate AS date))';
}

@Controller('api/v1')
export class FnSfr01403Controller {
  @Get('/personnel-status')
  async listPersonnelStatus(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const data = checks.queryOf(req.query);

    const statusType = text(data['statusType']);
    if (statusType === null) {
      throw new ApiError(422, 'STATUS_TYPE_REQUIRED', '현황 구분을 선택해 주세요.');
    }
    if (!STATUS_TYPES.includes(statusType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '현황 구분이 올바르지 않습니다.');
    }
    const startDate = text(data['startDate']);
    const endDate = text(data['endDate']);
    if ((startDate !== null && !/^\d{4}-\d{2}-\d{2}$/.test(startDate)) || (endDate !== null && !/^\d{4}-\d{2}-\d{2}$/.test(endDate))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간은 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const viewScope = text(data['viewScope']);
    if (viewScope !== null && SCOPE_RANK[viewScope] === undefined) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 범위가 올바르지 않습니다.');
    }
    const employmentStatus = text(data['employmentStatus']);
    if (employmentStatus !== null && employmentStatus !== '재직자' && employmentStatus !== '퇴직자') {
