    if (departmentId !== null && !/^\d+$/.test(departmentId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '부서가 올바르지 않습니다.');
    }
    const pageText = text(data['page']);
    const sizeText = text(data['size']);
