          'SELECT CAST(:startDate AS date) > CAST(:endDate AS date) AS "invalid"',
          { startDate, endDate },
        );
        if (check[0]['invalid'] === true) {
          throw new ApiError(422, 'INVALID_PERIOD', '조회 시작일은 종료일보다 늦을 수 없습니다.');
        }
